source="import json,subprocess\nnames=['twin-v2-bot-1','twin-v2-dash-1']\nfor name in names:\n d=json.loads(subprocess.check_output(['docker','inspect',name],text=True))[0]\n assert d['State']['Running']\n print(json.dumps({'container':name,'image':d['Image'],'revision':next((x[8:] for x in d['Config']['Env'] if x.startswith('GIT_SHA=')),None)}),flush=True)\ncode=\"\\nimport fs from 'node:fs';\\nimport path from 'node:path';\\nimport {createHash} from 'node:crypto';\\nimport {config} from './src/config.ts';\\nimport {mapFromV1} from './src/girls/map-v1.ts';\\nimport {validateVars} from './src/girls/template.ts';\\nimport {loadRawCatalogue,catalogueFromRaw} from './src/media.ts';\\nconst headers={apikey:config.supabaseKey,Authorization:'Bearer '+config.supabaseKey};\\nconst get=async p=>{const r=await fetch(config.supabaseUrl+'/rest/v1/'+p,{headers,signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error('database read '+r.status);return r.json();};\\nconst rows=await get('clones?select=*&order=slug');\\nconst fleet=JSON.parse(fs.readFileSync(path.join(config.dataDir,'_fleet.json'),'utf8'));\\nconst out=[];\\nfor(const c of rows.filter(c=>c.engine==='live')){\\n const mapped=mapFromV1(c);\\n const catalogue=catalogueFromRaw(await loadRawCatalogue(c.id));\\n const resp=await fetch('https://api.telegram.org/bot'+c.bot_token+'/getMe',{signal:AbortSignal.timeout(15000)});\\n const bot=await resp.json();\\n out.push({slug:c.slug,name:c.name,id:c.id,status:c.status,botValid:bot.ok===true,botUsername:bot.result?.username,missing:mapped.empty,birth:c.date_of_birth,photos:catalogue.filter(x=>x.kind==='photo').length,videos:catalogue.filter(x=>x.kind==='video').length,tips:c.tips_enabled,credits:c.v2_credits_enabled,memory:c.v2_memory_enabled});\\n}\\nconst watched=['src/fleet.ts','src/handover.ts','src/girls/template.ts','src/girls/map-v1.ts','dashboard/server.ts'];\\nconst hashes=Object.fromEntries(watched.map(p=>{const b=fs.readFileSync(p);return [p,createHash('sha1').update(Buffer.concat([Buffer.from('blob '+b.length+'\\\\0'),b])).digest('hex')];}));\\nconsole.log('V2_MIGRATION_PREFLIGHT '+JSON.stringify({at:new Date().toISOString(),commit:process.env.GIT_SHA,flags:Object.fromEntries(Object.entries(process.env).filter(([k])=>['V2_TIPS','V2_BUNDLES','V2_MEMORY','STAR_PRICE','V2_CREDITS'].includes(k))),hashes,fleetAt:fleet.at,running:Object.entries(fleet.girls).map(([slug,v])=>({slug,state:v.status,credits:v.credits?.applied?.enabled,tips:v.tips?.offersEnabled,memory:v.memory?.applied?.enabled})),creators:out,messagesSent:0,productionWrites:0}));\\n\"\np=subprocess.run(['docker','exec','-i','twin-v2-bot-1','node','--import','tsx','--input-type=module'],input=code,text=True,capture_output=True,timeout=180)\nif p.returncode: raise RuntimeError(p.stderr[-600:])\nfor line in p.stdout.splitlines():\n if line.startswith('V2_MIGRATION_PREFLIGHT '): print(line,flush=True)\n"
packed=base64.b64encode(gzip.compress(source.encode())).decode()
